// 3D model of the larynx from Z-Anatomy meshes (CC BY-SA 4.0, based on
// BodyParts3D), plus paths drawn for this app where Z-Anatomy has no model
// (vocal and vestibular folds, laryngeal nerves, superior thyroid and
// superior laryngeal arteries). Geometry lives in data/larynx-meshes.js,
// generated by tools/export_zanatomy.py. Coordinates are centimetres centred
// on the glottis: +y = superior, +z = anterior, and the patient's left is +x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.larynx = {
  // Default view: front and slightly right, as at a laryngectomy.
  camera: { target: [0, 0.4, 0.2], radius: 15, theta: -0.5, phi: 1.55 },

  // [theta, phi] for the view buttons. "Lateral" shows the right side (-x).
  // The second button looks down from above and behind, as at laryngoscopy.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [Math.PI, 0.45],
    anterior: [0, 1.55]
  },
  viewLabels: { inferior: "From above" },

  // Starting axial level (0 = bottom of the model, 1 = top): the glottis.
  sectionLevel: 0.45,

  look: {
    hyoid: { kind: "bone" },
    thyroid_cartilage: { kind: "cartilage" },
    cricoid: { kind: "cartilage" },
    arytenoids: { kind: "cartilage", color: 0xe9c6b6 },
    epiglottis: { kind: "cartilage", color: 0xe8cf9a },
    trachea: { kind: "cartilage", color: 0xd9cbb2 },
    thyrohyoid_membrane: { kind: "cartilage", color: 0xd8d4e4, opacity: 0.75 },
    cricothyroid_membrane: { kind: "cartilage", color: 0xd8d4e4, opacity: 0.85 },
    quadrangular_membrane: { kind: "cartilage", color: 0xd8d4e4, opacity: 0.7 },
    vocal_folds: { kind: "cartilage", color: 0xf4eee6 },
    vestibular_folds: { kind: "muscle", color: 0xd98a86 },
    pca: { kind: "muscle", color: 0xa4423f },
    lca: { kind: "muscle", color: 0x9c3d3c },
    interarytenoid: { kind: "muscle", color: 0x943a3b },
    thyroarytenoid: { kind: "muscle", color: 0xa13f3d },
    cricothyroid: { kind: "muscle", color: 0x943a3b },
    thyrohyoid: { kind: "muscle", color: 0x9a3c3c },
    sternothyroid: { kind: "muscle", color: 0x9c3d3c },
    sternohyoid: { kind: "muscle", color: 0xa4423f },
    omohyoid: { kind: "muscle", color: 0xa13f3d },
    constrictors: { kind: "muscle", color: 0x8f3739 },
    laryngopharynx: { kind: "muscle", color: 0xd99090, opacity: 0.55 },
    tongue: { kind: "muscle", color: 0xc06a62, opacity: 0.8 },
    thyroid: { kind: "gland", color: 0xa8423a, opacity: 0.8 },
    vertebrae: { kind: "bone", opacity: 0.6 },
    cca: { kind: "artery" },
    ita: { kind: "artery" },
    superior_thyroid_artery: { kind: "artery" },
    superior_laryngeal_artery: { kind: "artery" },
    ijv: { kind: "vein" },
    superior_thyroid_vein: { kind: "vein" },
    vagus: { kind: "nerve" },
    sln: { kind: "nerve" },
    ebsln: { kind: "nerve" },
    rln_right: { kind: "nerve" },
    rln_left: { kind: "nerve" }
  },

  build(THREE, h) {
    return h.fromMeshes("larynx", this.look);
  }
};
